StructuredTextModel.Text:
(*
  GET BETA FUNCTION
  Returns pressure-drop constant for given fluid and nozzle type
  Author: AhmadMohammad | Date: 2025-11-05
  β is in bar / (L/min)²
  Nozzle: 0=TX-0.60, 1=TX-2.5, 2=TX-4, 3=TX-8, 4=Hose6mm, 5=Hose18mm
  Fluid: 0=Water, 1=ISOXEL_5450, 2=DFAB_3D
*)
  IF iNozzle < 0 OR iNozzle > 5 THEN
  GetBeta := rBeta;
ELSE
  CASE iFluid OF
    0: rBeta := const_Beta_Water[iNozzle];
    1: rBeta := const_Beta_ISOXEL[iNozzle];
    2: rBeta := const_Beta_DFAB[iNozzle];
  ELSE
    rBeta := 0.0;
  END_CASE;
  
  GetBeta := rBeta;
END_IF;
